<?php $v=$value??[];$prefix=$name; ?><fieldset><legend>تاریخ پیشنهادی</legend><div class="fields"><label>تقویم<select name="<?= e($prefix) ?>[calendar]"><?php foreach(['jalali'=>'شمسی','gregorian'=>'میلادی','hijri'=>'قمری'] as $key=>$title): ?><option value="<?= $key ?>" <?= ($v['calendar']??'jalali')===$key?'selected':'' ?>><?= $title ?></option><?php endforeach ?></select></label><label>دقت تاریخ<select name="<?= e($prefix) ?>[precision]"><?php foreach(['unknown'=>'نامشخص','year'=>'سال','month'=>'سال و ماه','day'=>'تاریخ کامل'] as $key=>$title): ?><option value="<?= $key ?>" <?= ($v['precision']??'unknown')===$key?'selected':'' ?>><?= $title ?></option><?php endforeach ?></select></label><?php foreach(['year'=>'سال','month'=>'ماه','day'=>'روز'] as $key=>$title): ?><label><?= $title ?><input name="<?= e($prefix) ?>[<?= $key ?>]" inputmode="numeric" maxlength="4" value="<?= e($v[$key]??'') ?>"></label><?php endforeach ?></div><label class="check"><input type="checkbox" name="<?= e($prefix) ?>[is_approximate]" value="1" <?= !empty($v['is_approximate'])?'checked':'' ?>>تاریخ تقریبی است</label></fieldset>